     1	package cli
     2	
     3	import (
     4		"bytes"
     5		"context"
     6		"fmt"
     7		"io"
     8		"os/exec"
     9		"strings"
    10		"time"
    11	
    12		"github.com/entireio/cli/cmd/entire/cli/agent/claudecode"
    13		"github.com/entireio/cli/cmd/entire/cli/paths"
    14		"github.com/entireio/cli/cmd/entire/cli/settings"
    15	)
    16	
    17	const claudeCodeAgentName = "claude-code"
    18	
    19	type worktreeSetupIssue struct {
    20		ConfiguredWorktree        string
    21		MissingProjectSettings    bool
    22		MissingClaudeProjectHooks bool
    23		CurrentCaptureInactive    bool
    24	}
    25	
    26	func inspectWorktreeSetup(ctx context.Context) *worktreeSetupIssue {
    27		currentRoot, err := paths.WorktreeRoot(ctx)
    28		if err != nil {
    29			return nil
    30		}
    31	
    32		project, local, err := settings.FilesPresent(ctx)
    33		if err != nil {
    34			return nil
    35		}
    36		hasAnySettings := project || local
    37		if hasAnySettings {
    38			currentSettings, loadErr := LoadEntireSettings(ctx)
    39			if loadErr != nil || !currentSettings.Enabled {
    40				return nil
    41			}
    42		}
    43		hasPortableProjectSettings := project && settings.ProjectSettingsEnabledForWorktreeRoot(currentRoot)
    44	
    45		hasClaudeProjectHooks, err := claudecode.AreProjectHooksInstalledInWorktree(ctx, currentRoot)
    46		if err != nil {
    47			return nil
    48		}
    49		if hasPortableProjectSettings && hasClaudeProjectHooks {
    50			return nil
    51		}
    52	
    53		for _, sibling := range siblingWorktrees(ctx, currentRoot) {
    54			if !settings.ProjectSettingsEnabledForWorktreeRoot(sibling) ||
    55				!settings.IsSetUpAndEnabledForWorktreeRoot(ctx, sibling) {
    56				continue
    57			}
    58			hasHooks, hookErr := claudecode.AreProjectHooksInstalledInWorktree(ctx, sibling)
    59			if hookErr == nil && hasHooks {
    60				return &worktreeSetupIssue{
    61					ConfiguredWorktree:        sibling,
    62					MissingProjectSettings:    !hasPortableProjectSettings,
    63					MissingClaudeProjectHooks: !hasClaudeProjectHooks,
    64					CurrentCaptureInactive:    !hasAnySettings,
    65				}
    66			}
    67		}
    68		return nil
    69	}
    70	
    71	func siblingWorktrees(ctx context.Context, currentRoot string) []string {
    72		ctx, cancel := context.WithTimeout(ctx, 5*time.Second)
    73		defer cancel()
    74	
    75		cmd := exec.CommandContext(ctx, "git", "worktree", "list", "--porcelain", "-z")
    76		cmd.Dir = currentRoot
    77		output, err := cmd.Output()
    78		if err != nil {
    79			return nil
    80		}
    81		return parseSiblingWorktrees(output, normalizeWorktreePath(currentRoot))
    82	}
    83	
    84	func parseSiblingWorktrees(porcelain []byte, currentRoot string) []string {
    85		var worktrees []string
    86		var path string
    87		prunable := false
    88		bare := false
    89		for _, field := range bytes.Split(porcelain, []byte{0}) {
    90			line := string(field)
    91			switch {
    92			case line == "":
    93				if path != "" && !prunable && !bare && normalizeWorktreePath(path) != currentRoot {
    94					worktrees = append(worktrees, path)
    95				}
    96				path = ""
    97				prunable = false
    98				bare = false
    99			case strings.HasPrefix(line, "worktree "):
   100				path = strings.TrimPrefix(line, "worktree ")
   101			case line == "prunable" || strings.HasPrefix(line, "prunable "):
   102				prunable = true
   103			case line == "bare":
   104				bare = true
   105			}
   106		}
   107		return worktrees
   108	}
   109	
   110	func writeWorktreeSetupIssue(w io.Writer, issue *worktreeSetupIssue) {
   111		if issue == nil {
   112			return
   113		}
   114		fmt.Fprintln(w, "Claude Code worktree portability: INCOMPLETE")
   115		fmt.Fprintf(w, "  Entire capture is configured in another worktree: %s\n", issue.ConfiguredWorktree)
   116		fmt.Fprintf(w, "  Missing here: %s.\n", strings.Join(issue.missingLabels(), ", "))
